<template>
  <section v-if="instance" class="resource-panel" v-loading="loading"><div class="toolbar"><div><h2>{{t('productResources.statusTitle')}}</h2><p>{{t('productResources.statusDescription')}}</p></div><div v-if="canManage"><el-button plain @click="togglePublished">{{published?t('productResources.unpublish'):t('productResources.publish')}}</el-button><el-button type="primary" @click="openCreate">{{t('productResources.addTarget')}}</el-button></div></div><el-table :data="monitors"><el-table-column prop="name" :label="t('productResources.name')" min-width="130"/><el-table-column prop="targetUrl" :label="t('productResources.targetUrl')" min-width="220" show-overflow-tooltip/><el-table-column prop="lastStatus" :label="t('productResources.latestStatus')" width="110"/><el-table-column :label="t('productResources.status')" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?t('productResources.enabled'):t('productResources.pause')}}</el-tag></template></el-table-column><el-table-column :label="t('productResources.actions')" width="250" fixed="right"><template #default="{row}"><el-button link @click="check(row.id)">{{t('productResources.runCheck')}}</el-button><template v-if="canManage"><el-button link @click="edit(row)">{{t('productResources.edit')}}</el-button><el-button link :type="row.enabled?'warning':'primary'" @click="toggle(row)">{{row.enabled?t('productResources.pause'):t('productResources.resume')}}</el-button><el-button link type="danger" @click="remove(row)">{{t('productResources.delete')}}</el-button></template></template></el-table-column></el-table><el-empty v-if="!monitors.length&&!loading" :description="t('productResources.empty')"/>
    <el-dialog v-model="dialog" :title="editing?t('productResources.edit'):t('productResources.addTarget')" width="520px" destroy-on-close><el-form label-position="top"><el-form-item :label="t('productResources.name')"><el-input v-model="form.name"/></el-form-item><el-form-item :label="t('productResources.targetUrl')"><el-input v-model="form.targetUrl"/></el-form-item><el-form-item :label="t('productResources.method')"><el-select v-model="form.method"><el-option label="GET" value="GET"/><el-option label="HEAD" value="HEAD"/></el-select></el-form-item><el-form-item :label="t('productResources.intervalSeconds')"><el-input-number v-model="form.intervalSec" :min="60"/></el-form-item><el-form-item :label="t('productResources.successStatusCodes')"><el-input v-model="form.successStatusCodesText" placeholder="200, 201, 204"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">{{t('cancel')}}</el-button><el-button type="primary" @click="save">{{t('productResources.save')}}</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import { ref, watch } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import type { DeveloperProductInstanceDto, DeveloperStatusMonitorDto } from '@/client/types.gen'; import { developerProductService } from '@/service/developerProductService'; import { i18ns } from '@/locales'
const { t }=i18ns; const props=defineProps<{instance?:DeveloperProductInstanceDto;canManage:boolean}>();const loading=ref(false),monitors=ref<DeveloperStatusMonitorDto[]>([]),dialog=ref(false),editing=ref<DeveloperStatusMonitorDto>(),published=ref(false),form=ref({name:'',targetUrl:'',method:'GET' as 'GET'|'HEAD',intervalSec:60,successStatusCodesText:'200'});const load=async()=>{if(!props.instance)return;loading.value=true;try{const[nextMonitors,page]=await Promise.all([developerProductService.listMonitorResources(props.instance.id),props.canManage?developerProductService.getStatusPageResource(props.instance.id):Promise.resolve(undefined)]);monitors.value=nextMonitors;published.value=page?.statusPagePublished||false}finally{loading.value=false}};const openCreate=()=>{editing.value=undefined;form.value={name:'',targetUrl:'',method:'GET',intervalSec:60,successStatusCodesText:'200'};dialog.value=true};const edit=(row:DeveloperStatusMonitorDto)=>{editing.value=row;form.value={name:row.name,targetUrl:row.targetUrl,method:row.method as 'GET'|'HEAD',intervalSec:row.intervalSec,successStatusCodesText:(row.successStatusCodes||[200]).join(', ')};dialog.value=true};const save=async()=>{if(!props.instance)return;const successStatusCodes=form.value.successStatusCodesText.split(',').map((code)=>Number(code.trim())).filter((code)=>Number.isInteger(code)&&code>=100&&code<=599);if(!successStatusCodes.length){ElMessage.error(t('productResources.invalidStatusCodes'));return}const body={name:form.value.name,targetUrl:form.value.targetUrl,method:form.value.method,intervalSec:form.value.intervalSec,successStatusCodes};if(editing.value)await developerProductService.updateMonitorResource(props.instance.id,editing.value.id,body);else await developerProductService.createMonitorResource(props.instance.id,body);dialog.value=false;await load();ElMessage.success(t('updateSuccess'))};const toggle=async(row:DeveloperStatusMonitorDto)=>{if(!props.instance)return;await developerProductService.updateMonitorResource(props.instance.id,row.id,{enabled:!row.enabled});await load()};const check=async(id:string)=>{if(!props.instance)return;await developerProductService.checkMonitorResource(props.instance.id,id);await load();ElMessage.success(t('success'))};const remove=async(row:DeveloperStatusMonitorDto)=>{if(!props.instance)return;await ElMessageBox.confirm(`${t('delete')} ${row.name}?`,t('confirmDelete'),{type:'warning'});await developerProductService.deleteMonitorResource(props.instance.id,row.id);await load();ElMessage.success(t('deleteSuccess'))};const togglePublished=async()=>{if(!props.instance)return;published.value=!published.value;await developerProductService.updateStatusPageResource(props.instance.id,{published:published.value});ElMessage.success(t('updateSuccess'))};watch(()=>props.instance?.id,load,{immediate:true})
</script><style scoped>.toolbar{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}.toolbar h2{margin:0 0 6px;font-size:17px}.toolbar p{margin:0;color:var(--el-text-color-secondary)}</style>
